-- Dados do CupolaOS das tabelas criadas depois da carga de 24/09 (gerado de data.sql).
-- Não sobrescreve nada: on conflict do nothing. Linhas que apontam para conta ou agente
-- que não existe no banco ficam de fora. Seguro para rodar mais de uma vez.

-- agentes_por_cliente: 22 de 22 linha(s) do dump
insert into agencia.agentes_por_cliente (agente_id, cliente_id, liberado)
select v.agente_id::text, v.cliente_id::text, v.liberado::boolean
from (values
  ($d$news$d$, $d$jba$d$, $d$f$d$),
  ($d$news$d$, $d$incorpore$d$, $d$f$d$),
  ($d$news$d$, $d$stela-patelli-exclusiv$d$, $d$f$d$),
  ($d$news$d$, $d$grupo-paladio$d$, $d$f$d$),
  ($d$news$d$, $d$porto-seguro$d$, $d$f$d$),
  ($d$news$d$, $d$mafi$d$, $d$f$d$),
  ($d$news$d$, $d$lago$d$, $d$f$d$),
  ($d$criador-de-post-news$d$, $d$grupo-paladio$d$, $d$f$d$),
  ($d$criador-de-post-news$d$, $d$incorpore$d$, $d$f$d$),
  ($d$news$d$, $d$konex$d$, $d$f$d$),
  ($d$criador-de-post-news$d$, $d$konex$d$, $d$f$d$),
  ($d$criador-de-post-news$d$, $d$lago$d$, $d$f$d$),
  ($d$criador-de-post-news$d$, $d$mafi$d$, $d$f$d$),
  ($d$criador-de-post-news$d$, $d$porto-seguro$d$, $d$f$d$),
  ($d$criador-de-post-news$d$, $d$stela-patelli-exclusiv$d$, $d$f$d$),
  ($d$conteudo-para-redes$d$, $d$porto-seguro$d$, $d$f$d$),
  ($d$conteudo-para-redes$d$, $d$roque-imoveis$d$, $d$f$d$),
  ($d$conteudo-para-redes$d$, $d$stela-patelli-exclusiv$d$, $d$f$d$),
  ($d$conteudo-para-redes$d$, $d$pedro-granado$d$, $d$f$d$),
  ($d$conteudo-para-redes$d$, $d$lago$d$, $d$f$d$),
  ($d$conteudo-para-redes$d$, $d$konex$d$, $d$f$d$),
  ($d$conteudo-para-redes$d$, $d$cred-aluga$d$, $d$f$d$)
) as v (agente_id, cliente_id, liberado)
where exists (select 1 from agencia.agentes a where a.id = v.agente_id) and exists (select 1 from agencia.clientes c where c.id = v.cliente_id)
on conflict do nothing;

